const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const R = input[0];
const N = input[1];

const cheapest = new Array(101).fill(Infinity);

for (let i = 0; i < N; i++) {
  const type = input[2 + i * 2];
  const price = input[3 + i * 2];
  cheapest[type] = Math.min(cheapest[type], price);
}

const prices = cheapest.filter(price => price !== Infinity).sort((a, b) => a - b);

let spent = 0;
let count = 0;

for (const price of prices) {
  if (spent + price > R) break;
  spent += price;
  count++;
}

console.log(count);
